{
    "predictors": [
        {
            "name": "Supplier Network Centrality",
            "construction": "Calculate the centrality of a firm's supplier network using supply chain data, emphasizing the number of connections a firm has within its network.",
            "rationale": "Firms with extensive supplier networks may have better access to inputs and more bargaining power, leading to improved operational efficiencies.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Social Media Sentiment",
            "construction": "Aggregate sentiment scores from social media mentions over the past month, using sentiment analysis algorithms to quantify positivity or negativity.",
            "rationale": "Positive sentiment on social media may lead to increased investor interest and momentum.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Green Investment Index",
            "construction": "Ratio of investments in environmentally sustainable projects to total assets, using firm disclosures and sustainability reports.",
            "rationale": "Firms investing in green projects may benefit from regulatory incentives and changing consumer preferences towards sustainability.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Satisfaction Score",
            "construction": "Average employee satisfaction score from third-party survey data or internal surveys, scaled between 0 and 1.",
            "rationale": "Higher employee satisfaction may lead to higher productivity and lower turnover, enhancing firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Innovation Output Ratio",
            "construction": "Number of patents filed over the last year divided by total R&D expenditure.",
            "rationale": "Efficient innovation processes may indicate a firm's ability to convert R&D spending into profitable products.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Retention Rate",
            "construction": "Percentage of customers retained over the past year, obtained from company reports or industry data.",
            "rationale": "High customer retention can indicate stable revenue streams and strong competitive positioning.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Data Breach Impact",
            "construction": "Negative of the change in stock price following a publicized data breach, normalized by market capitalization.",
            "rationale": "Firms that minimize the impact of data breaches may have better risk management practices, preserving investor confidence.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Tax Efficiency Ratio",
            "construction": "Ratio of net income to pre-tax income over the last fiscal year.",
            "rationale": "Firms with more efficient tax strategies may retain more earnings, which can be reinvested for growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Board Diversity Score",
            "construction": "Diversity score measured as the proportion of diverse (gender, ethnicity) members on the board of directors.",
            "rationale": "Diverse boards may lead to better decision-making and risk management through varied perspectives.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Strategic Acquisition Index",
            "construction": "Number of strategic acquisitions over the past three years divided by total assets, using merger and acquisition data.",
            "rationale": "Firms actively engaging in strategic acquisitions may exhibit growth through synergies and market expansion.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
